#!/usr/bin/env python3
# ADJUST-GL-V1 (2026-07-09): le panel image-adjust passe du SVG (courbe 33pts
# + 2 GaussianBlur = lag 4K + effets timides) a un fragment shader WebGL —
# tone-mapping par pixel a 60fps, reference Pixelmator Basic: exposure (+-2
# stops), highlights/shadows ponderes par luminance, blackpoint, brightness,
# contrast, texture (high-pass fin) et clarity (high-pass mipmap). Texture GPU
# uploadee 1x par cam; chaque slider = 1 uniform + redraw. Le canvas suit le
# rect exact de frameImg (zoom/pan via cssText, throttle rAF), pointer-events
# none, insere juste au-dessus de img SOUS les overlays de markers. Fallback:
# alert si WebGL indisponible. Rollback: git checkout -- tools/calib.html.
# Idempotent.
import base64, sys
p = 'tools/calib.html'
src = open(p).read()
if 'ADJUST-GL-V1' in src:
    print('ok  deja patche'); sys.exit(0)
a1 = "  // \u2500\u2500 #4: image adjust \u2500\u2500"
a2 = "  window._mkAdjState = st;   // test hook"
assert a1 in src, 'ancre debut (#4 image adjust) introuvable'
assert a2 in src, 'ancre fin (test hook) introuvable'
i1 = src.index(a1)
i2 = src.index(a2) + len(a2)
NEW = base64.b64decode("").decode()
open(p, 'w').write(src[:i1] + NEW + src[i2:])
print('EDIT calib.html: ADJUST-GL-V1 (SVG -> WebGL)')
